// Runs every hour from the schedule, or right away when /review calls this workflow.
// Schedule: only chats whose recall hour is now; daily words are split over the sessions.
// /review: only the chat that asked, whatever the hour.
// Words due today (or earlier) come first. If nothing is due, the chat gets the one word whose
// review is closest (sent early), so there is always something to practise.
const cfg = $('Config').first().json;
const run = $('Run Context').first().json;
const plain = (p) => ((p && (p.rich_text || p.title)) || []).map(t => t.plain_text).join('').trim();
const now = $now.setZone(cfg.timezone);
const today = now.toISODate();
const hoursOf = (v) => {
  const h = String(v || '').split(',').filter(Boolean).map(Number).filter(n => Number.isInteger(n) && n >= 0 && n <= 23);
  return h.length ? h : String(cfg.default_recall_hours).split(',').map(Number);
};
const settings = {};
for (const row of ($('Get All Settings').first().json.results || [])) {
  const p = row.properties || {};
  const words = parseInt(plain(p['Daily Words']), 10);
  settings[plain(p['Chat ID'])] = {
    source: plain(p['Source Language']).toLowerCase() || cfg.default_source,
    hours: hoursOf(plain(p['Recall Hours'])),
    words: words >= 1 && words <= 20 ? words : cfg.default_daily_words
  };
}
const fallback = { source: cfg.default_source, hours: hoursOf(''), words: cfg.default_daily_words };
const esc = (v) => String(v || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escRe = (v) => v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const nextReview = (page) => String((((page.properties || {})['Next Review'] || {}).date || {}).start || '').slice(0, 10);

// Group the words by chat. Notion already sorted them: closest Next Review first.
const byChat = {};
for (const page of ($json.results || [])) {
  const p = page.properties || {};
  const chat = plain(p['Chat ID']);
  const s = settings[chat] || fallback;
  const lang = ((p['Language'] || {}).select || {}).name || '';
  if (!chat || !plain(p['Word']) || lang !== s.source) continue;
  if (run.manual && chat !== run.chat_id) continue;
  (byChat[chat] = byChat[chat] || []).push(page);
}

// One quiz card: the word is blanked in its sentence and hidden in a spoiler.
const card = (page, chat, early) => {
  const p = page.properties || {};
  const word = plain(p['Word']);
  const wordLang = ((p['Language'] || {}).select || {}).name || '';
  const sentence = plain(p['Sentence']);
  // blank the word (or its first 5 letters for conjugated forms) inside the sentence.
  // Chinese and Japanese have no spaces, so only the exact word is blanked there.
  const exact = new RegExp(escRe(word), 'iu');
  const stem = new RegExp(escRe(word.split(' ')[0].slice(0, 5)) + '\\p{L}*', 'iu');
  const spaced = !['zh', 'ja'].includes(wordLang);
  const re = exact.test(sentence) ? exact : (spaced && word.length >= 5 && stem.test(sentence) ? stem : null);
  const cloze = sentence && re ? sentence.replace(re, '_____') : '';
  const translation = plain(p['Translation']);
  const lines = [];
  if (early) lines.push('<i>nothing due today, here is a word to review early</i>', '');
  lines.push('🫐 <b>' + esc(plain(p['Definition'])) + '</b>');
  if (translation) lines.push('🪷 ' + esc(translation));
  if (cloze) lines.push('', '<i>' + esc(cloze) + '</i>');
  lines.push('', 'answer: <tg-spoiler>' + esc(word) + ' ' + esc(plain(p['Part of Speech'])) + '</tg-spoiler>');
  // due = false for early words: Mark As Sent is skipped, so their schedule is not pulled forward
  return { json: { chat_id: chat, page_id: page.id.replace(/-/g, ''), due: !early, text: lines.join('\n') } };
};

const out = [];
for (const chat of Object.keys(byChat)) {
  const s = settings[chat] || fallback;
  if (!run.manual && !s.hours.includes(now.hour)) continue;
  const pages = byChat[chat];
  const due = pages.filter(page => nextReview(page) && nextReview(page) <= today);
  const perSession = Math.ceil(s.words / s.hours.length);
  if (due.length) due.slice(0, perSession).forEach(page => out.push(card(page, chat, false)));
  // early word: always on /review, but only at the first session of the day on the schedule
  else if (run.manual || now.hour === s.hours[0]) out.push(card(pages[0], chat, true));
}

// /review with no saved words at all: one item that says so (Anything To Send? sends it).
if (run.manual && !out.length) {
  return [{ json: { chat_id: run.chat_id, empty: true,
    text: 'no words to review yet 🌀\nsave some first with /article &lt;topic&gt; or /add &lt;word&gt;' } }];
}
return out; // scheduled run with nothing to send -> no items -> the run stops here

// Who asked? The schedule trigger has no chat_id; /review (main workflow) passes one.
// manual = true means: send now, only to that chat, whatever the hour.
const chat = String($json.chat_id || '').trim();
return [{ json: { manual: chat !== '', chat_id: chat } }];
